pub fn solve_cookie_distribution(a: u8, b: u8, n: u8, m: u8) -> bool {
    // Widen to avoid overflow when summing u8 values.
    let a16 = a as u16;
    let b16 = b as u16;
    let n16 = n as u16;
    let m16 = m as u16;

    // Each special guest needs one cookie from each pile.
    if a16 < m16 || b16 < m16 {
        return false;
    }

    // Total cookies must cover n regular (1 each) + m special (in addition to the per-pile constraint).
    (a16 + b16) >= (n16 + m16)
}

